export function extractors(keys, base) {
  return keys.map((key, index) => {
    const extract = (req, res) => key + (base + index) + JSON.stringify(req) + String(res);
    return { key, extract };
  });
}

const stored = new Map([["r:a", { url: "/a" }], ["n:n", 7], ["s:s", "text"]]);
const registry = { get: (key) => stored.get(key) };

